public final class MainActivity extends FragmentActivity {
 private static final int BLUE=0xff2459e8,INK=0xff14213a,MUTED=0xff66738b,BG=0xfff3f6fb;
 private static final int ACCOUNT=101,AUTH=102,RESTORE=103,CSV=104,EXPORT=105;
 private static final String[] TYPES={"APP","WEB","Thẻ tín dụng","Khóa cửa","Email"};
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final Handler timer=new Handler(Looper.getMainLooper());
 private VaultStore store;private BiometricVault bio;private VaultCrypto.Session session;private LinearLayout content,list;private TextView status;private EditText master;
 private boolean busy,systemFlow,destroyed;private int generation;private long lastTouch;private String screen="login",filter="Tất cả",query="",accessToken,exportText;private Account account;private Runnable afterGoogle;private AlertDialog dialog;private BiometricPrompt prompt;
 private interface Work<T>{T run()throws Exception;}private interface Done<T>{void accept(T value)throws Exception;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);store=new VaultStore(this);bio=new BiometricVault(this);lastTouch=System.currentTimeMillis();login();timer.post(tick);}
 private final Runnable tick=new Runnable(){public void run(){if(session!=null&&System.currentTimeMillis()-lastTouch>300000)lock();if(!destroyed)timer.postDelayed(this,1000);}};
 @Override public boolean dispatchTouchEvent(MotionEvent e){lastTouch=System.currentTimeMillis();return super.dispatchTouchEvent(e);}
 @Override protected void onStop(){super.onStop();if(!systemFlow)lock();}
 @Override protected void onDestroy(){destroyed=true;generation++;if(session!=null)session.destroy();session=null;if(prompt!=null)prompt.cancelAuthentication();timer.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
 @Override public void onBackPressed(){if(busy)return;if(session!=null&&!screen.equals("vault")){vault();return;}if(session!=null)ask("Khóa và thoát?","Kho sẽ khóa trước khi thoát.",()->{lock();finish();});else super.onBackPressed();}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(14));return d;}
 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(6),0,dp(6));return t;}
 private void heading(String title,String hint){TextView t=text(title,26,INK);t.setTypeface(null,Typeface.BOLD);content.addView(t);if(hint!=null)content.addView(text(hint,14,MUTED));}
 private Button button(String title,Runnable action,boolean primary){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(15);b.setTextColor(primary?Color.WHITE:INK);b.setBackground(shape(primary?BLUE:Color.WHITE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.topMargin=dp(10);b.setLayoutParams(p);b.setOnClickListener(v->{if(!busy)action.run();});return b;}
 private EditText input(LinearLayout parent,String title,String value,boolean secret){parent.addView(text(title,13,MUTED));LinearLayout row=new LinearLayout(this);EditText e=new EditText(this);e.setText(value);e.setSingleLine(true);e.setTextSize(16);e.setTextColor(INK);e.setSaveEnabled(false);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);e.setInputType(secret?129:1);e.setPadding(dp(12),dp(8),dp(12),dp(8));e.setBackground(shape(Color.WHITE));row.addView(e,new LinearLayout.LayoutParams(0,dp(52),1));if(secret){e.setTransformationMethod(PasswordTransformationMethod.getInstance());Button show=new Button(this);show.setText("Hiện");show.setAllCaps(false);show.setContentDescription("Hiện hoặc ẩn "+title);show.setOnClickListener(v->{boolean visible=e.getTransformationMethod()!=null;e.setTransformationMethod(visible?null:PasswordTransformationMethod.getInstance());show.setText(visible?"Ẩn":"Hiện");e.setSelection(e.length());});row.addView(show,new LinearLayout.LayoutParams(dp(72),dp(52)));}parent.addView(row);return e;}
 private void base(String page,boolean nav){screen=page;LinearLayout root=column();root.setPadding(dp(20),dp(16),dp(20),dp(14));root.setBackgroundColor(BG);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(20)+insets.getSystemWindowInsetLeft(),dp(16)+insets.getSystemWindowInsetTop(),dp(20)+insets.getSystemWindowInsetRight(),dp(14)+insets.getSystemWindowInsetBottom());return insets;});status=text("",13,BLUE);status.setVisibility(View.GONE);root.addView(status);ScrollView scroll=new ScrollView(this);content=column();content.setPadding(0,0,0,dp(16));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(nav){LinearLayout bar=new LinearLayout(this);for(String tab:new String[]{"Kho","Phân loại","Cài đặt"})bar.addView(button(tab,()->{if(tab.equals("Kho"))vault();else if(tab.equals("Phân loại"))categories();else settings();},false),new LinearLayout.LayoutParams(0,dp(52),1));root.addView(bar);}setContentView(root);}
 private void toast(String message){if(!destroyed)Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
 private void error(Throwable e){toast(e.getMessage()==null?"Không hoàn tất được thao tác.":e.getMessage());}
 private void ask(String title,String message,Runnable action){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("Hủy",null).setPositiveButton("Đồng ý",(d,w)->{if(!busy)action.run();}).show();}
 private <T> void work(String message,Work<T> job,Done<T> done){if(busy)return;busy=true;status.setText(message);status.setVisibility(View.VISIBLE);int ticket=generation;io.execute(()->{T value=null;Throwable error=null;try{value=job.run();}catch(Exception e){error=e;}final T result=value;final Throwable failure=error;runOnUiThread(()->{busy=false;if(destroyed||ticket!=generation){if(result instanceof VaultCrypto.Session)((VaultCrypto.Session)result).destroy();return;}status.setVisibility(View.GONE);if(failure!=null){error(failure);return;}try{done.accept(result);}catch(Exception e){error(e);}});});}
 private void lock(){generation++;if(session!=null)session.destroy();session=null;accessToken=null;account=null;afterGoogle=null;exportText=null;if(master!=null)master.setText("");if(dialog!=null)dialog.dismiss();if(!destroyed)login();}
 private void clearFailures(){getSharedPreferences("state",0).edit().remove("failures").apply();}
 private void login(){base("login",false);heading("SafeInCloud","Kho mật khẩu cá nhân · Android native");if(!store.exists()){heading("Thiết lập lần đầu",null);content.addView(button("Tạo kho trên thiết bị",()->create(false),true));content.addView(button("Mở kho từ Google Drive",()->google(this::pull),false));content.addView(button("Khôi phục bản sao lưu",()->pick(RESTORE),false));return;}master=input(content,"Mật khẩu chính","",true);master.setImeOptions(6);master.setOnEditorActionListener((v,id,event)->{if(id==6){passwordLogin();return true;}return false;});content.addView(button("Mở khóa",this::passwordLogin,true));if(bio.enabled())content.addView(button("Vân tay / Khuôn mặt",this::biometricLogin,false));}
 private void passwordLogin(){if(busy)return;char[] pw=master.getText().toString().toCharArray();master.setText("");if(pw.length==0){toast("Hãy nhập mật khẩu chính.");return;}work("Đang mở khóa…",()->{try{return VaultCrypto.open(store.read(),pw);}catch(AEADBadTagException e){return null;}finally{Arrays.fill(pw,'\0');}},opened->{if(opened==null){SharedPreferences prefs=getSharedPreferences("state",0);int count=prefs.getInt("failures",0)+1;prefs.edit().putInt("failures",count).apply();toast("Sai mật khẩu hoặc kho đã bị thay đổi. Lần thử: "+count);if(count>5)ask("Tạo database mới?","Chọn lại Google và đặt mật khẩu mới. Kho cũ được giữ riêng.",()->create(true));return;}session=opened;clearFailures();vault();});}
 private void create(boolean requireGoogle){accessToken=null;account=null;base("create",false);heading("Tạo kho mới",requireGoogle?"Chọn lại Google. Kho cũ chỉ thay sau khi lưu kho mới thành công.":"Mật khẩu tối thiểu 6 ký tự. Kết nối Drive sau trong Cài đặt.");TextView chosen=text("Chưa chọn Google",14,MUTED);if(requireGoogle){content.addView(button("Chọn lại tài khoản Google",()->google(()->chosen.setText("Đã chọn: "+account.name)),false));content.addView(chosen);}EditText pw=input(content,"Mật khẩu mới","",true),repeat=input(content,"Nhập lại mật khẩu","",true);content.addView(button("Tạo database mới",()->{char[] p=pw.getText().toString().toCharArray(),r=repeat.getText().toString().toCharArray();if(Character.codePointCount(p,0,p.length)<6||!Arrays.equals(p,r)){Arrays.fill(p,'\0');Arrays.fill(r,'\0');toast("Mật khẩu cần ít nhất 6 ký tự và hai lần nhập phải giống nhau.");return;}Arrays.fill(r,'\0');if(requireGoogle&&accessToken==null){Arrays.fill(p,'\0');toast("Hãy chọn lại tài khoản Google.");return;}String token=accessToken;pw.setText("");repeat.setText("");work("Đang mã hóa và tạo kho mới…",()->{VaultCrypto.Session next=null;try{next=VaultCrypto.create(p);String envelope=VaultCrypto.seal(next,next.items);if(requireGoogle)DriveClient.upload(envelope,token);store.replace(envelope);return next;}catch(Exception e){if(next!=null)next.destroy();throw e;}finally{Arrays.fill(p,'\0');}},next->{if(session!=null)session.destroy();session=next;bio.clear();clearFailures();filter="Tất cả";query="";vault();toast("Đã tạo kho mới. Kho cũ được giữ riêng.");});},true));content.addView(button("Hủy",()->{if(session!=null)settings();else login();},false));}
 private void vault(){if(session==null){login();return;}base("vault",true);heading("Kho mật khẩu",session.items.length()+" mục · Mã hóa trên thiết bị");EditText search=input(content,"Tìm kiếm",query,false);content.addView(button("+ Thêm mục",()->edit(null),true));list=column();content.addView(list);renderList();search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();renderList();}public void afterTextChanged(Editable e){}});}
 private void renderList(){if(session==null)return;list.removeAllViews();int count=0;for(int i=0;i<session.items.length();i++){JSONObject item=session.items.optJSONObject(i);JSONObject f=item.optJSONObject("fields");String type=item.optString("category","WEB"),login=f.optString("Login","");String hay=(item.optString("title")+" "+login+" "+f.optString("URL")).toLowerCase(Locale.ROOT);if((!filter.equals("Tất cả")&&!filter.equals(type))||!hay.contains(query.toLowerCase(Locale.ROOT)))continue;Button row=button(item.optString("title")+"\n"+type+(login.isEmpty()?"":" · "+login),()->detail(item),false);row.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);row.setPadding(dp(14),0,dp(14),0);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(78));lp.topMargin=dp(10);row.setLayoutParams(lp);list.addView(row);count++;}if(count==0)list.addView(text("Chưa có mục phù hợp. Thêm mục hoặc Import CSV trong Cài đặt.",15,MUTED));}
 private void categories(){if(session==null)return;base("categories",true);heading("Phân loại",null);content.addView(button("Tất cả",()->{filter="Tất cả";vault();},false));for(String t:TYPES)content.addView(button(t,()->{filter=t;vault();},false));}
 private boolean secret(String n){return !n.toLowerCase(Locale.ROOT).matches("login|url|notes|tài khoản|ghi chú|địa chỉ");}
 private void copy(String value){ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("SafeInCloud",value));toast("Đã sao chép; tự xóa sau 30 giây nếu clipboard chưa đổi.");timer.postDelayed(()->{if(cm.hasPrimaryClip()&&cm.getPrimaryClip().getItemCount()>0&&value.contentEquals(cm.getPrimaryClip().getItemAt(0).coerceToText(this))){if(Build.VERSION.SDK_INT>=28)cm.clearPrimaryClip();else cm.setPrimaryClip(ClipData.newPlainText("",""));}},30000);}
 private void detail(JSONObject item){if(session==null)return;base("detail",true);heading(item.optString("title"),item.optString("category","WEB"));JSONObject f=item.optJSONObject("fields");for(Iterator<String> keys=f.keys();keys.hasNext();){String name=keys.next(),value=f.optString(name,"");content.addView(text(name,13,MUTED));TextView v=text(secret(name)?"••••••••••":value,18,INK);content.addView(v);if(secret(name)){Button show=button("Hiện",()->{},false);show.setOnClickListener(x->{boolean visible=show.getText().equals("Hiện");v.setText(visible?value:"••••••••••");show.setText(visible?"Ẩn":"Hiện");if(visible)timer.postDelayed(()->{v.setText("••••••••••");show.setText("Hiện");},15000);});content.addView(show);}content.addView(button("Sao chép",()->copy(value),false));}content.addView(button("Chỉnh sửa",()->edit(item),true));content.addView(button("Xóa mục",()->ask("Xóa mục?","Xóa khỏi kho hiện tại. Bản sao cũ vẫn giữ dữ liệu.",()->{JSONArray next=new JSONArray();for(int i=0;i<session.items.length();i++){JSONObject o=session.items.optJSONObject(i);if(!o.optString("id").equals(item.optString("id")))next.put(o);}save(next,this::vault);}),false));}
 private static final class Field{EditText name,value;LinearLayout row;}
 private void addField(List<Field> fields,LinearLayout parent,String name,String value){Field f=new Field();f.row=column();f.name=input(f.row,"Tên trường",name,false);f.name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});f.value=input(f.row,"Giá trị",value,true);f.row.addView(button("Xóa trường",()->{fields.remove(f);parent.removeView(f.row);},false));fields.add(f);parent.addView(f.row);}
 private void edit(JSONObject item){if(session==null)return;base("edit",false);heading(item==null?"Thêm mục":"Chỉnh sửa",null);EditText title=input(content,"Tên mục",item==null?"":item.optString("title"),false);title.setFilters(new InputFilter[]{new InputFilter.LengthFilter(300)});Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,TYPES));type.setMinimumHeight(dp(52));content.addView(type);type.setSelection(1);if(item!=null){for(int i=0;i<TYPES.length;i++)if(TYPES[i].equals(item.optString("category")))type.setSelection(i);}List<Field> fields=new ArrayList<>();LinearLayout container=column();content.addView(container);try{JSONObject f=item==null?new JSONObject("{\"Login\":\"\",\"Password\":\"\",\"URL\":\"\",\"Notes\":\"\",\"OTP\":\"\"}"):item.getJSONObject("fields");for(Iterator<String> it=f.keys();it.hasNext();){String n=it.next();addField(fields,container,n,f.optString(n));}}catch(Exception e){error(e);}content.addView(button("+ Thêm trường",()->addField(fields,container,"",""),false));content.addView(button("Tạo mật khẩu ngẫu nhiên",()->{for(Field f:fields)if(f.name.getText().toString().equals("Password")){f.value.setText(VaultCrypto.generate());return;}addField(fields,container,"Password",VaultCrypto.generate());},false));content.addView(button("Lưu",()->{try{String name=title.getText().toString().trim();if(name.isEmpty())throw new IllegalArgumentException("Hãy nhập tên mục.");JSONObject values=new JSONObject();for(Field f:fields){String n=f.name.getText().toString().trim();if(n.isEmpty()||values.has(n))throw new IllegalArgumentException("Tên trường trống hoặc trùng.");values.put(n,f.value.getText().toString());}String id=item==null?UUID.randomUUID().toString():item.getString("id");JSONObject record=new JSONObject().put("id",id).put("title",name).put("category",type.getSelectedItem().toString()).put("fields",values).put("updatedAt",Instant.now().toString());JSONArray next=new JSONArray();for(int i=0;i<session.items.length();i++){JSONObject o=session.items.getJSONObject(i);if(!o.getString("id").equals(id))next.put(o);}next.put(record);save(next,()->detail(record));}catch(Exception e){error(e);}},true));content.addView(button("Hủy",this::vault,false));}
 private void save(JSONArray next,Runnable done){if(session==null)return;VaultCrypto.Session snapshot=new VaultCrypto.Session(session.key.clone(),session.salt.clone(),next);work("Đang mã hóa và lưu…",()->{try{store.write(VaultCrypto.seal(snapshot,next));return next;}finally{snapshot.destroy();}},items->{session.items=items;done.run();toast("Đã lưu mã hóa.");});}
 private void settings(){if(session==null)return;base("settings",true);heading("Cài đặt","Dữ liệu & bảo mật");content.addView(button(bio.enabled()?"Tắt vân tay / khuôn mặt":"Bật vân tay / khuôn mặt",()->{if(bio.enabled())ask("Tắt sinh trắc học?","Mật khẩu chính vẫn giữ nguyên.",()->{bio.clear();settings();});else enableBiometric();},false));content.addView(text("Sinh trắc học mạnh do Android xác minh. Khóa được bảo vệ bằng Android Keystore, vô hiệu khi đăng ký sinh trắc học thay đổi.",13,MUTED));content.addView(button("Sao lưu lên Google Drive",()->google(()->{String token=accessToken;work("Đang sao lưu Google Drive…",()->{DriveClient.upload(store.read(),token);return true;},ok->toast("Đã lưu bản sao mã hóa trên Drive."));}),false));content.addView(button("Mở kho từ Google Drive",()->google(this::pull),false));content.addView(button("Import CSV",()->pick(CSV),false));content.addView(button("Xuất bản sao lưu mã hóa",()->{try{export(store.read());}catch(Exception e){error(e);}},false));content.addView(button("Khôi phục bản sao lưu",()->pick(RESTORE),false));content.addView(button("Xuất kho trước khi tạo mới",()->{try{export(store.previous());}catch(Exception e){toast("Chưa có bản kho trước đó.");}},false));content.addView(button("Tạo database mới",()->ask("Tạo database mới?","Chọn lại Google. Kho cũ được giữ riêng.",()->create(true)),false));content.addView(button("Khóa kho",this::lock,true));content.addView(text("SafeInCloud Native 1.0.0 · AES-256-GCM\nTự khóa khi rời app hoặc không thao tác 5 phút.",13,MUTED));}
 private boolean hasBiometrics(){if(BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG)==BiometricManager.BIOMETRIC_SUCCESS)return true;toast("Cần đăng ký vân tay hoặc khuôn mặt bảo mật mạnh trong cài đặt Android. Vẫn có thể dùng mật khẩu chính.");return false;}
 private void authenticate(Cipher cipher,Done<Cipher> success,Runnable cancel){systemFlow=true;prompt=new BiometricPrompt(this,ContextCompat.getMainExecutor(this),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){if(destroyed)return;systemFlow=false;lastTouch=System.currentTimeMillis();try{if(r.getCryptoObject()==null||r.getCryptoObject().getCipher()==null)throw new SecurityException("Thiếu khóa xác thực.");success.accept(r.getCryptoObject().getCipher());}catch(Exception e){error(e);}}@Override public void onAuthenticationError(int code,CharSequence message){systemFlow=false;cancel.run();toast("Chưa hoàn tất xác minh. Có thể dùng mật khẩu chính.");}});prompt.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("SafeInCloud").setSubtitle("Xác minh vân tay hoặc khuôn mặt").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG).setNegativeButtonText("Dùng mật khẩu").build(),new BiometricPrompt.CryptoObject(cipher));}
 private void enableBiometric(){if(session==null||!hasBiometrics())return;LinearLayout form=column();form.setPadding(dp(20),0,dp(20),0);EditText pw=input(form,"Xác nhận mật khẩu chính","",true);dialog=new AlertDialog.Builder(this).setTitle("Bật sinh trắc học").setView(form).setNegativeButton("Hủy",null).setPositiveButton("Xác nhận",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{char[] password=pw.getText().toString().toCharArray();pw.setText("");work("Đang xác nhận mật khẩu…",()->{try{VaultCrypto.Session check=VaultCrypto.open(store.read(),password);check.destroy();return true;}finally{Arrays.fill(password,'\0');}},ok->{dialog.dismiss();if(session==null)return;authenticate(bio.prepareEnrollment(),verified->{if(session==null)throw new SecurityException("Kho đã khóa.");bio.finishEnrollment(verified,session.key,session.salt);settings();toast("Đã bật sinh trắc học.");},bio::clear);});}));dialog.show();}
 private void biometricLogin(){if(busy||!hasBiometrics())return;try{JSONObject v=VaultCrypto.validate(store.read());byte[] salt=VaultCrypto.bytes(v.getString("salt"));authenticate(bio.prepareUnlock(salt),verified->{byte[] raw=bio.finishUnlock(verified,salt);work("Đang mở khóa…",()->{try{return VaultCrypto.openWithKey(v,raw,salt);}catch(Exception e){Arrays.fill(raw,(byte)0);throw e;}},opened->{session=opened;clearFailures();vault();});},()->{});}catch(Exception e){error(e);}}
 private void pick(int code){systemFlow=true;startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),code);}
 private void export(String envelope){exportText=envelope;systemFlow=true;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"SafeInCloud-"+Instant.now().toString().replace(':','-')+".vault"),EXPORT);}
 private String read(Uri uri)throws Exception{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Không đọc được file.");byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>10*1024*1024)throw new IOException("File vượt quá 10 MB.");out.write(b,0,n);}return out.toString("UTF-8");}}
 private void restore(String envelope){try{VaultCrypto.validate(envelope);ask("Mở kho từ sao lưu?","Kho hiện tại được giữ riêng. Cần mật khẩu của kho được mở.",()->work("Đang khôi phục bản mã…",()->{store.replace(envelope);return true;},ok->{bio.clear();clearFailures();lock();toast("Nhập mật khẩu của kho vừa mở.");}));}catch(Exception e){error(e);}}
 private void pull(){String token=accessToken;work("Đang tải kho từ Drive…",()->DriveClient.pull(token),this::restore);}
 private void google(Runnable action){afterGoogle=action;accessToken=null;account=null;try{systemFlow=true;startActivityForResult(AccountPicker.newChooseAccountIntent(new AccountPicker.AccountChooserOptions.Builder().setAllowableAccountsTypes(Collections.singletonList("com.google")).setAlwaysShowAccountPicker(true).build()),ACCOUNT);}catch(Exception e){systemFlow=false;error(e);}}
 private void authorize(Account a){status.setText("Đang kết nối Google…");status.setVisibility(View.VISIBLE);Identity.getAuthorizationClient(this).authorize(AuthorizationRequest.builder().setAccount(a).setRequestedScopes(Collections.singletonList(new Scope(DriveClient.SCOPE))).build()).addOnSuccessListener(r->{if(r.hasResolution()){try{systemFlow=true;startIntentSenderForResult(r.getPendingIntent().getIntentSender(),AUTH,null,0,0,0);}catch(Exception e){systemFlow=false;error(e);}}else authorized(r);}).addOnFailureListener(e->{systemFlow=false;status.setVisibility(View.GONE);toast("Chưa kết nối Google. Cần cấu hình OAuth Android đúng package và SHA-1 của bản ký; xem hướng dẫn Native trong repository. Kho trên thiết bị được giữ nguyên.");});}
 private void authorized(AuthorizationResult r){systemFlow=false;status.setVisibility(View.GONE);accessToken=r.getAccessToken();if(accessToken==null){toast("Google chưa cấp quyền Drive.");return;}Runnable action=afterGoogle;afterGoogle=null;if(action!=null)action.run();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);systemFlow=false;if(result!=RESULT_OK||data==null){exportText=null;afterGoogle=null;return;}try{if(request==ACCOUNT){String name=data.getStringExtra(AccountManager.KEY_ACCOUNT_NAME);if(name==null)throw new IllegalArgumentException("Chưa chọn tài khoản.");account=new Account(name,"com.google");authorize(account);}else if(request==AUTH)authorized(Identity.getAuthorizationClient(this).getAuthorizationResultFromIntent(data));else if(request==EXPORT){String value=exportText;exportText=null;if(value==null)return;work("Đang xuất bản sao mã hóa…",()->{try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException("Không ghi được file.");out.write(value.getBytes(StandardCharsets.UTF_8));}return true;},ok->toast("Đã xuất bản sao mã hóa."));}else if(request==RESTORE)work("Đang đọc bản sao lưu…",()->read(data.getData()),this::restore);else if(request==CSV){if(session==null){toast("Hãy mở kho trước.");return;}work("Đang kiểm tra CSV…",()->CsvImport.parse(read(data.getData())),incoming->{if(incoming.length()==0){toast("File mẫu chưa có dữ liệu.");return;}ask("Import CSV?","Nhập "+incoming.length()+" mục. Mục trùng vẫn được nhập.",()->{if(session==null)return;JSONArray next=new JSONArray();for(int i=0;i<session.items.length();i++)next.put(session.items.opt(i));for(int i=0;i<incoming.length();i++)next.put(incoming.opt(i));save(next,this::vault);});});}}catch(Exception e){error(e);}}
}
